---- MONITORS ----
------------------

-- See https://wiki.hypr.land/Configuring/Basics/Monitors/
hl.monitor({
    output   = "",
    mode     = "highres@highrr",
    position = "auto",
    scale    = 1,
})
---------------------
---- MY PROGRAMS ----
---------------------

-- Set programs that you use
local terminal    = "kitty"
local fileManager = "dolphin"
local menu        = "hyprlauncher"


-------------------
---- AUTOSTART ----
-------------------

-- See https://wiki.hypr.land/Configuring/Basics/Autostart/

-- Autostart necessary processes (like notifications daemons, status bars, etc.)
-- Or execute your favorite apps at launch like this:
--
hl.on("hyprland.start", function () 
--   hl.exec_cmd(terminal)
--   hl.exec_cmd("nm-applet")
   hl.exec_cmd("waybar"); --- & hyprpaper & firefox
   hl.exec_cmd("swaync");
   hl.exec_cmd("awww-daemon");
   hl.exec_cmd("sh -c 'sleep 1; waypaper --restore'");
   hl.exec_cmd("wl-clip-persist --clipboard regular");
   hl.exec_cmd("wl-paste --type text --watch cliphist store");
   hl.exec_cmd("wl-paste --type image --watch cliphist store");
 end)


-------------------------------
---- ENVIRONMENT VARIABLES ----
-------------------------------

-- See https://wiki.hypr.land/Configuring/Advanced-and-Cool/Environment-variables/

hl.env("XCURSOR_SIZE", "24")
hl.env("HYPRCURSOR_SIZE", "24")


-- Ortam Degiskenleri (Portal servisinin Hyprland'i tanimasi icin sart)
hl.env("XDG_CURRENT_DESKTOP", "Hyprland")
hl.env("XDG_SESSION_TYPE", "wayland")
hl.env("XDG_SESSION_DESKTOP", "Hyprland")

-- Yöntem A: Doğrudan hl.config tablosunun içinde (exec_once listesi olarak)
hl.config({
    exec_once = {
        "dbus-update-activation-environment --systemd WAYLAND_DISPLAY XDG_CURRENT_DESKTOP",
    },
})

-- Hyprland basladiginda bu degiskenleri systemd ve dbus servislerine aktar:

