---- INPUT ----
---------------

hl.config({
    input = {
        kb_layout     = "tr",
        kb_variant    = "",
        kb_model      = "",
        kb_options    = "",
        kb_rules      = "",

        follow_mouse  = 1,
        accel_profile = "flat", -- Fare ivmesini kapatır (1:1 ham hareket)
