        touchpad = {
            natural_scroll = true,
        },
    },

    cursor = {
        no_hardware_cursors = true, -- NVIDIA'da imleç takılmasını/titremesini çözer
    },
})


hl.gesture({
    fingers = 3,
    direction = "horizontal",
    action = "workspace"
})

